            var parkCommentsObj = typeof parkCommentsRaw === 'string'
                ? JSON.parse(parkCommentsRaw) : (parkCommentsRaw || []);
            var parkCommentList = Array.isArray(parkCommentsObj)
                ? parkCommentsObj
