{"command":"python3 -c "
import json, re
rev = json.load(open('outputs/pr_review.json'))
added = {}
cur = None; new = 0; inhunk = False
for ln in open('/tmp/full_diff.txt'):
    if ln.startswith('diff --git'):
        cur = ln.split(' b/')[-1].strip(); added[cur] = set(); inhunk = False
    elif ln.startswith('@@'):
        new = int(re.search(r'\+(\d+)', ln).group(1)); inhunk = True
    elif inhunk and cur:
        if ln.startswith('+++') or ln.startswith('---'): continue
        if ln.startswith('+'): added[cur].add(new); new += 1
        elif ln.startswith('-'): pass
        else: new += 1
allok = True
for c in rev['inlineComments']:
    ok = c['line'] in added.get(c['path'], set())
    allok = allok and ok
    print(('OK  ' if ok else 'MISS'), c['path'], c['line'])
print('ALL IN DIFF' if allok else 'SOME MISSING')
""}
